import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t_str = next(iterator)
        T = int(t_str)
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            n_str = next(iterator)
            N = int(n_str)

            goals = []
            for _ in range(N):
                goals.append(int(next(iterator)))
        except StopIteration:
            break

        if N < 2:
            results.append("UNFIT")
            continue

        min_val = goals[0]
        max_diff = -1

        for i in range(1, N):
            current_goal = goals[i]
            diff = current_goal - min_val

            if diff > max_diff:
                max_diff = diff

            if current_goal < min_val:
                min_val = current_goal

        if max_diff <= 0:
            results.append("UNFIT")
        else:
            results.append(str(max_diff))

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == "__main__":
    solve()
